const categories=[
 {id:'outfit',label:'Outfits',icon:'👗',tip:'Every day is a runway when you feel like you.',items:[['daydream','Sunday dress','🌷'],['sailor','Sailor sweet','⚓'],['hoodie','Cozy cutie','🧸'],['magical','Moon magic','🌙']]},
 {id:'hair',label:'Hair',icon:'💇',tip:'A little hair magic changes everything.',items:[['long-cocoa','Cocoa waves','🤎'],['bob-rose','Rose bob','🌹'],['twin-plum','Plum twins','🍇'],['long-lilac','Lilac locks','💜'],['bob-midnight','Midnight bob','🌌']]},
 {id:'shoes',label:'Shoes',icon:'👠',tip:'The perfect finishing touch, from comfy to fancy.',items:[['flats','Petal flats','🌸'],['boots','Cloud boots','🥾'],['heels','Star heels','✨']]},
 {id:'accessory',label:'Extras',icon:'🎀',tip:'Add a little sparkle (or a whole lot).',items:[['none','Bare & lovely','☺️'],['bow','Sweet bow','🎀'],['flower','Daisy pin','🌼'],['crown','Tiny crown','👑'],['glasses','Cute specs','👓']]},
 {id:'scene',label:'Scenes',icon:'🌅',tip:'Set the mood for your next style story.',items:[['cotton','Candy skies','🍬'],['garden','Secret garden','🌿'],['night','Moonlit night','🌙'],['cafe','Peachy café','☕']]}
];
const defaults={outfit:'daydream',hair:'long-cocoa',shoes:'flats',accessory:'none',scene:'cotton'};
const state={...defaults};let active='outfit';
const $=s=>document.querySelector(s), tabs=$('#tabs'), grid=$('#itemGrid');
const hideIds=['outfit-dress','outfit-sailor','outfit-hoodie','outfit-magical','shoes-flats','shoes-boots','shoes-heels','hairBack-long','hairBack-bob','hairBack-twin','hairFront-long','hairFront-bob','hairFront-twin','acc-bow','acc-flower','acc-crown','acc-glasses'];
function show(id,on=true){const el=document.getElementById(id);if(el)el.style.display=on?'':'none'}
function colorHair(color1,color2){const stops=document.querySelectorAll('#hair stop');stops[0].setAttribute('stop-color',color1);stops[1].setAttribute('stop-color',color2)}
function apply(){hideIds.forEach(id=>show(id,false));
 const outfitMap={daydream:'outfit-dress',sailor:'outfit-sailor',hoodie:'outfit-hoodie',magical:'outfit-magical'};show(outfitMap[state.outfit]);
 const shoeMap={flats:'shoes-flats',boots:'shoes-boots',heels:'shoes-heels'};show(shoeMap[state.shoes]);
 const hairMap={'long-cocoa':['long','#9c5e74','#613b61'],'bob-rose':['bob','#df8397','#914f78'],'twin-plum':['twin','#9469c2','#51396f'],'long-lilac':['long','#b89ae4','#72589e'],'bob-midnight':['bob','#6474a9','#36416f']};const [style,c1,c2]=hairMap[state.hair];show('hairBack-'+style);show('hairFront-'+style);colorHair(c1,c2);
 const accMap={bow:'acc-bow',flower:'acc-flower',crown:'acc-crown',glasses:'acc-glasses'};if(state.accessory!=='none')show(accMap[state.accessory]);
 const scene=$('#scene');scene.className='scene'+(state.scene==='cotton'?'':' '+state.scene);const sceneInfo={cotton:'cotton candy skies',garden:'secret garden',night:'moonlit dream',cafe:'peachy little café'};$('#sceneLabel').textContent=sceneInfo[state.scene];
}
function renderTabs(){tabs.innerHTML='';categories.forEach(c=>{const b=document.createElement('button');b.className='tab'+(active===c.id?' active':'');b.innerHTML=`${c.icon} ${c.label}`;b.setAttribute('aria-pressed',active===c.id);b.onclick=()=>{active=c.id;renderTabs();renderItems()};tabs.appendChild(b)})}
function renderItems(){const cat=categories.find(c=>c.id===active);$('#categoryTitle').textContent=cat.label;$('#itemCount').textContent=`${cat.items.length} pieces`;$('#tipText').textContent=cat.tip;grid.innerHTML='';cat.items.forEach(([key,name,emoji])=>{const b=document.createElement('button');b.className='item'+(state[active]===key?' selected':'');b.setAttribute('aria-label',name);b.setAttribute('aria-pressed',state[active]===key);b.innerHTML=`<span class="item-emoji">${emoji}</span><span class="item-name">${name}</span>`;b.onclick=()=>{state[active]=key;apply();renderItems();if(active==='outfit')$('#lookName').textContent=name;b.animate([{transform:'scale(.94)'},{transform:'scale(1)'}],{duration:180})};grid.appendChild(b)})}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
function randomize(){categories.forEach(c=>{const list=c.items.map(x=>x[0]);state[c.id]=list[Math.floor(Math.random()*list.length)]});apply();renderItems();const outfit=categories[0].items.find(x=>x[0]===state.outfit);$('#lookName').textContent=outfit[1];toast('A fresh look, just for you! ✨')}
function reset(){Object.assign(state,defaults);apply();renderItems();$('#lookName').textContent='Sunday daydream';$('#heart').textContent='♡';toast('Back to your Sunday daydream 🌸')}
function save(){try{localStorage.setItem('petal-prism-look',JSON.stringify(state));$('#heart').textContent='♥';toast('Look saved to your stylebook! 💖')}catch(e){toast('Your look is ready to enjoy! 💖')}}
$('#random').onclick=randomize;$('#randomTop').onclick=randomize;$('#reset').onclick=reset;$('#saveTop').onclick=save;$('#heart').onclick=()=>{const h=$('#heart');h.textContent=h.textContent==='♡'?'♥':'♡';toast(h.textContent==='♥'?'Added to favorites! 💗':'Favorite removed')};
try{const saved=JSON.parse(localStorage.getItem('petal-prism-look'));if(saved){categories.forEach(c=>{if(c.items.some(x=>x[0]===saved[c.id]))state[c.id]=saved[c.id]})}}catch(e){}
apply();renderTabs();renderItems();if(state.outfit!==defaults.outfit)$('#lookName').textContent=categories[0].items.find(x=>x[0]===state.outfit)[1];

